const input = $input.first().json;
const value = (name, label) => String(input[name] ?? input[label] ?? '').trim();
const splitLines = (text) => text.split(/\r?\n/).map((line) => line.trim()).filter(Boolean);
const practiceLines = splitLines(value('test_practices', 'Test practices (one Name | public website URL per line; URL optional)'));
const recipientLines = splitLines(value('test_emails', 'Test emails (one email | practice name per line; practice optional if one practice)'));
if (!practiceLines.length && !recipientLines.length) throw new Error('Enter at least one test practice or test email.');
if (practiceLines.length > 20 || recipientLines.length > 100) throw new Error('Use at most 20 test practices and 100 test emails in one preview.');
const practices = practiceLines.map((line) => {
  const parts = line.split('|').map((part) => part.trim());
  if (parts.length > 2 || !parts[0]) throw new Error('Each test practice must be Name | public website URL (URL optional).');
  let public_website_url = '';
  if (parts[1]) {
    let parsed;
    try { parsed = new URL(parts[1]); } catch { throw new Error('Invalid test practice URL: ' + parts[1]); }
    if (parsed.protocol !== 'https:' || parsed.username || parsed.password || parsed.search || parsed.hash) throw new Error('Test practice URLs must be HTTPS without credentials, query, or fragment.');
    public_website_url = parsed.href.replace(/\/$/, '');
  }
  return { name: parts[0], public_website_url };
});
const byName = new Map();
for (const practice of practices) {
  const key = practice.name.toLowerCase();
  if (byName.has(key)) throw new Error('Duplicate test practice: ' + practice.name);
  byName.set(key, practice);
}
const recipients = recipientLines.map((line) => {
  const parts = line.split('|').map((part) => part.trim());
  if (parts.length > 2 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(parts[0] || '')) throw new Error('Each test email must be email | practice name.');
  const practiceName = parts[1] || (practices.length === 1 ? practices[0].name : '');
  if (practiceName && !byName.has(practiceName.toLowerCase())) throw new Error('Test email references an unknown test practice: ' + practiceName);
  return { email: parts[0].toLowerCase(), practice_name: practiceName };
});
if (new Set(recipients.map((recipient) => recipient.email)).size !== recipients.length) throw new Error('Each test email may appear only once.');
return [{ json: { mode: 'TEST_PREVIEW_ONLY', preview_only: true, test_practices: practices, test_recipients: recipients, practice_count: practices.length, recipient_count: recipients.length, message: 'No email sent. No campaign or practice saved. No WordPress post or static-site release created.' } }];
